
/* --------------------------------------------------------------------------
   9. Case seeds — fictional
   -------------------------------------------------------------------------
   Written for the simulator. No real person, institution, transaction or
   enforcement action is depicted. The typologies reflect patterns described
   in published FATF, FIU and supervisory material.
   Roughly half of these are legitimate activity that a monitoring engine
   cannot distinguish from laundering without investigation — the point of
   those cases is that unusual is not the same as suspicious.
   -------------------------------------------------------------------------- */

const FIC_SRC = [{ l:"FATF — methods and trends", u:"https://www.fatf-gafi.org/en/publications/Methodsandtrends.html" }];
function FICR(what, extra){
  return { what: what,
    facts: "Entirely fictional. Written for the simulator. " + (extra || "The pattern reflects typologies described in published FATF and financial intelligence unit material; no real customer, institution or case is depicted."),
    sources: FIC_SRC };
}

